    #[test]
    fn field_id_roundtrip_large_class_id() {
        // Interpreter round i1 wave 52, lane L1: the top bit of the class
        // half is the static mark ([`STATIC_FIELD_ID_MARK`]), so the largest
        // class id is 2^31 - 1 (the store hands out dense ids far below).
        let cid = crate::classloading::ClassId::new(0x5EAD_BEEF);
        let field_index: usize = 1234;
        let fid = encode_field_id(cid, field_index);
        let (decoded_cid, decoded_idx) = decode_field_id(fid);
        assert_eq!(decoded_cid, cid);
        assert_eq!(decoded_idx, field_index);
        let (marked_cid, marked_idx) = decode_field_id(fid | STATIC_FIELD_ID_MARK);
        assert_eq!(
            marked_cid, cid,
            "the static mark is not part of the class id"
        );
        assert_eq!(marked_idx, field_index);
    }

