    /// gci i5g/g1r (the G1 half of `gcf-f1j-...`): the in-native band's heap
    /// rule. Generational always; G1 only with
    /// `CRATONVM_JNI_IN_NATIVE_BAND_AT_PAUSE_G1` (default ON since vi6-g1r,
    /// `=0` kills).
    #[test]
    fn gci_i5g_g1r_band_heap_rule_admits_g1_only_with_its_switch() {
        use crate::config::{GcAlgorithm, VmConfig};
        const NAME: &str = "CRATONVM_JNI_IN_NATIVE_BAND_AT_PAUSE_G1";
        let g1 = SharedVm::new(VmConfig {
            gc_algorithm: GcAlgorithm::G1,
            ..VmConfig::default()
        });
        let generational = SharedVm::new(VmConfig {
            gc_algorithm: GcAlgorithm::Generational,
            ..VmConfig::default()
        });
        // t1 w8 JNICUT: the switch is latched per VM (`JniSwitches::read_flags`),
        // so each arm reads its switches under its own override.
        let read = |value: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(&[(NAME, value)], || {
                JniSwitches::read_flags(false)
            })
        };
        cratonvm_types::flags::with_thread_overrides(&[(NAME, None)], || {
            assert!(in_native_band_at_pause_g1_enabled(), "flipped: unset reads ON");
        });
        let unset = read(None);
        assert!(unset.in_native_band_at_pause_g1, "latched ON when unset");
        assert!(in_native_band_heap_admits(&g1, &unset), "G1 by default");
        assert!(in_native_band_heap_admits(&generational, &unset), "Generational always");
        let on = read(Some("1"));
        assert!(in_native_band_heap_admits(&g1, &on), "G1 with the switch");
        assert!(in_native_band_heap_admits(&generational, &on));
        let off = read(Some("0"));
        assert!(!off.in_native_band_at_pause_g1);
        assert!(!in_native_band_heap_admits(&g1, &off), "=0 reads OFF");
        assert!(in_native_band_heap_admits(&generational, &off), "Generational always");
        // The pure rule leaves it on (outside the package rule).
        assert!(jni_switches_from(None, None, None, None, None).in_native_band_at_pause_g1);
    }

    // -----------------------------------------------------------------------
    // gcd d3/k: a Java thread inside a JNI native method
    // (`CRATONVM_JNI_NATIVE_TRANSITIONS`)
    // -----------------------------------------------------------------------

    /// Restores this thread's transition overrides on drop (an assertion's
    /// unwind included), so no test leaves one set for a later test that the
    /// harness runs on the same OS thread.
    struct TransitionOverrides;

    impl TransitionOverrides {
        fn set(native: Option<bool>, indirect: Option<bool>, foreign: Option<bool>) -> Self {
            JNI_NATIVE_CALL.with(|t| t.test_override.set(native));
            INDIRECT_LOCALS_TEST_OVERRIDE.with(|c| c.set(indirect));
            FOREIGN_TRANSITIONS_TEST_OVERRIDE.with(|c| c.set(foreign));
            TransitionOverrides
        }
    }

    impl Drop for TransitionOverrides {
        fn drop(&mut self) {
            let _ = JNI_NATIVE_CALL.try_with(|t| t.test_override.set(None));
            let _ = INDIRECT_LOCALS_TEST_OVERRIDE.try_with(|c| c.set(None));
            let _ = FOREIGN_TRANSITIONS_TEST_OVERRIDE.try_with(|c| c.set(None));
        }
    }

    /// A registered Java thread of `shared` for a dispatch test: its registry
    /// entry shares the thread's `gc_block_state` and `root_snapshot`, as a
    /// started thread's does. The caller marks it dead when done.
    fn d3k_java_thread(shared: &SharedVm, name: &str) -> Box<JvmThread> {
        let registry = &shared.threads.thread_registry;
        let tid = registry.next_thread_id();
        let jt = Box::new(JvmThread::new(tid, name));
        registry.register(tid, name, None);
        registry.set_gc_block_state(tid, jt.gc_block_state.clone());
        registry.set_root_snapshot(tid, jt.root_snapshot.clone());
        jt
    }

    fn d3k_in_native(jt: *const JvmThread) -> bool {
        // SAFETY: the test's own boxed `JvmThread`; only an atomic is read.
        unsafe { &*jt }
            .gc_block_state
            .in_blocked_region
            .load(std::sync::atomic::Ordering::Acquire)
    }

    /// `gcd-d2i-jni-native-methods-are-counted-mutators`: with the native
    /// transitions and indirect locals on, a Java thread inside a JNI native
    /// (a `JniNativeCall`, as `dispatch_jni_native` opens it around the C
    /// call) is excluded from another thread's stop-the-world pause -- the
    /// pause completes its census without it -- and reads RUNNABLE; a JNIEnv
    /// function it calls while the pause holds does not run until the pause
    /// ends, hands out an indirect local, and returns the thread to native;
    /// the call's end takes it out of native. Before the fix the thread was a
    /// counted mutator for the whole call: the pause waited for the native.
    #[test]
    fn a_java_thread_in_a_jni_native_holds_no_pause_and_its_jni_functions_wait_one_out() {
        use std::sync::atomic::{AtomicBool, Ordering};
        use std::sync::mpsc;
        use std::time::Duration;
        const WAIT: Duration = Duration::from_secs(30);
        let _guard = PROCESS_VM_TEST_LOCK.lock();
        let (shared, main_tid) = w10c_vm(crate::config::GcAlgorithm::Generational);
        let (to_main, from_native) = mpsc::channel::<Result<&'static str, String>>();
        let (to_native, from_main) = mpsc::channel::<()>();
        let returned = Arc::new(AtomicBool::new(false));
        let vm = Arc::clone(&shared);
        let done = Arc::clone(&returned);
        let native = std::thread::spawn(move || -> Result<(), String> {
            let _flags = TransitionOverrides::set(Some(true), Some(true), None);
            let mut jt = d3k_java_thread(&vm, "d3k-native");
            let tid = jt.thread_id;
            let jt_ptr: *mut JvmThread = &mut *jt;
            let result = {
                let _jni = JniTls::context(&vm).with_thread(jt_ptr);
                // The dispatch's implicit local frame.
                push_local_frame(16);
                let run = || -> Result<(), String> {
                    let call = JniNativeCall::enter(raw_local_escapes());
                    if !d3k_in_native(jt_ptr) {
                        return Err("the native call went into native".into());
                    }
                    if vm.threads.thread_registry.java_block_state(tid) != 0 {
                        return Err("a thread in native reads RUNNABLE".into());
                    }
                    let _ = to_main.send(Ok("in native"));
                    if from_main.recv_timeout(WAIT).is_err() {
                        return Err("the pause never came".into());
                    }
                    let text = CString::new("d3k in native").unwrap();
                    let s = jni_new_string_utf(get_jni_env(), text.as_ptr());
                    done.store(true, Ordering::SeqCst);
                    if s == 0 || !is_indirect_local_tag(s) {
                        return Err(format!(
                            "NewStringUTF answered {s:#x}, not an indirect local"
                        ));
                    }
                    if !d3k_in_native(jt_ptr) {
                        return Err("a JNIEnv function returns the thread to native".into());
                    }
                    if jstring_text(get_jni_env(), s).as_deref() != Some("d3k in native") {
                        return Err("the local reads back".into());
                    }
                    drop(call);
                    if d3k_in_native(jt_ptr) {
                        return Err("the call's end leaves native".into());
                    }
                    Ok(())
                };
                let r = run();
                if let Err(e) = &r {
                    let _ = to_main.send(Err(e.clone()));
                }
                r
            };
            vm.threads.thread_registry.mark_dead(tid);
            drop(jt);
            result
        });
        match from_native.recv_timeout(WAIT) {
            Ok(Ok("in native")) => {}
            other => {
                let _ = to_native.send(());
                let joined = native.join();
                panic!("the native thread did not reach native: {other:?} / {joined:?}");
            }
        }
        let alive = shared.threads.thread_registry.alive_count() as u32;
        assert_eq!(alive, 2, "main and the thread in native");
        assert!(shared.mem.gc_barrier.request_stw(main_tid, alive));
        let mut pause = PauseHeld(&shared, false);
        assert_eq!(
            shared.mem.gc_barrier.pending_count(),
            0,
            "the thread in native is excluded from the pause"
        );
        shared.mem.gc_barrier.wait_for_all();
        to_native.send(()).expect("the native thread waits");
        std::thread::sleep(Duration::from_millis(150));
        assert!(
            !returned.load(Ordering::SeqCst),
            "NewStringUTF must not run while another thread's pause holds"
        );
        pause.complete();
        native
            .join()
            .expect("the native thread does not panic")
            .expect("the in-native protocol");
        assert!(returned.load(Ordering::SeqCst));
        drop(pause);
    }

    /// The call stays a counted mutator -- byte-for-byte the old path --
    /// whenever a moving collection in the native window could strand a raw
    /// local the native holds: the flag off, indirect locals off (the
    /// `CRATONVM_JNI_INDIRECT_LOCALS=0` representation), or a receiver/argument
    /// recorded raw. And a call a
    /// JNIEnv function handed a raw local stays counted from that function on.
    #[test]
    fn a_jni_native_call_stays_counted_wherever_a_raw_local_could_escape() {
        let (shared, _main_tid) = w10c_vm(crate::config::GcAlgorithm::Generational);
        let mut jt = d3k_java_thread(&shared, "d3k-counted");
        let tid = jt.thread_id;
        let jt_ptr: *mut JvmThread = &mut *jt;
        {
            let _jni = JniTls::context(&shared).with_thread(jt_ptr);
            push_local_frame(16);

            // The flag off: inert.
            let _flags = TransitionOverrides::set(Some(false), Some(true), None);
            let call = JniNativeCall::enter(raw_local_escapes());
            assert!(!d3k_in_native(jt_ptr), "flag off: counted");
            drop(call);
            drop(_flags);

            // Raw locals (indirect off): inert.
            let _flags = TransitionOverrides::set(Some(true), Some(false), None);
            let call = JniNativeCall::enter(raw_local_escapes());
            assert!(!d3k_in_native(jt_ptr), "raw locals: counted");
            drop(call);
            drop(_flags);

            let _flags = TransitionOverrides::set(Some(true), Some(true), None);
            // A receiver or argument that went out raw.
            let before = raw_local_escapes();
            note_raw_local_escape();
            let call = JniNativeCall::enter(before);
            assert!(!d3k_in_native(jt_ptr), "a raw argument: counted");
            drop(call);

            // In native, then a JNIEnv function hands out a raw local.
            let call = JniNativeCall::enter(raw_local_escapes());
            assert!(d3k_in_native(jt_ptr), "both on: in native");
            {
                let fx = ForeignJniEntry::enter();
                assert!(!d3k_in_native(jt_ptr), "a JNIEnv function runs counted");
                note_raw_local_escape();
                drop(fx);
            }
            assert!(
                !d3k_in_native(jt_ptr),
                "a raw escape keeps the call counted"
            );
            {
                // Later functions of the same call are inert.
                let fx = ForeignJniEntry::enter();
                assert!(fx.native.is_none());
            }
            drop(call);
            assert!(!d3k_in_native(jt_ptr));
            assert!(
                JNI_NATIVE_CALL.with(|t| t.record.borrow().is_none()),
                "the call's record is gone"
            );
        }
        shared.threads.thread_registry.mark_dead(tid);
    }

    /// Nesting: a native that Java calls from inside a JNIEnv up-call of an
    /// in-native native brackets its own C call and restores the enclosing
    /// call's record, which the up-call's function then puts back in native.
    #[test]
    fn a_nested_jni_native_call_restores_the_enclosing_record() {
        let (shared, _main_tid) = w10c_vm(crate::config::GcAlgorithm::Generational);
        let mut jt = d3k_java_thread(&shared, "d3k-nested");
        let tid = jt.thread_id;
        let jt_ptr: *mut JvmThread = &mut *jt;
        {
            let _jni = JniTls::context(&shared).with_thread(jt_ptr);
            let _flags = TransitionOverrides::set(Some(true), Some(true), None);
            push_local_frame(16);
            let outer = JniNativeCall::enter(raw_local_escapes());
            assert!(d3k_in_native(jt_ptr));
            {
                // The outer native's `Call*Method`: out of native...
                let fx = ForeignJniEntry::enter();
                assert!(!d3k_in_native(jt_ptr));
                // ...Java calls another native, which goes into native...
                push_local_frame(16);
                let inner = JniNativeCall::enter(raw_local_escapes());
                assert!(d3k_in_native(jt_ptr), "the inner call is in native");
                drop(inner);
                assert!(!d3k_in_native(jt_ptr), "back in the up-call, counted");
                let outer_back = JNI_NATIVE_CALL
                    .with(|t| t.record.borrow().as_ref().is_some_and(|r| !r.in_native));
                assert!(outer_back, "the outer record is back, out of native");
                drop(fx);
            }
            assert!(d3k_in_native(jt_ptr), "the outer native is in native again");
            drop(outer);
            assert!(!d3k_in_native(jt_ptr));
        }
        shared.threads.thread_registry.mark_dead(tid);
    }

    /// gci i16/sn (`CRATONVM_DEBUG_SUSPEND_AT_NATIVE_TRANSITION`): a thread in
    /// a JNI native in native that an agent's `SuspendThread` holds stops at
    /// its next JNIEnv entry -- the full entry and the leaf window alike --
    /// still in native, so another thread's pause completes without it
    /// meanwhile, and runs the function once resumed. With the switch off it
    /// runs the function while suspended, as before (finding 6 of
    /// `gci-i15rb-vm-default-path-changes-review-findings-FIXED-20261017`).
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn gci_i16sn_a_suspended_thread_in_native_stops_at_its_next_jni_entry() {
        use std::sync::atomic::{AtomicU32, Ordering};
        use std::sync::mpsc;
        use std::time::Duration;
        const WAIT: Duration = Duration::from_secs(30);
        let _lock = crate::runtime::jvmti::jvmti_registry_test_lock();
        let (shared, main_tid) = w10c_vm(crate::config::GcAlgorithm::Generational);
        shared
            .debug
            .debugger_gates
            .set_suspend_at_native_transition(true);
        let entered = Arc::new(AtomicU32::new(0));
        let (to_main, from_native) = mpsc::channel::<Result<u64, String>>();
        // One message per JNIEnv entry the native makes: `true` = a leaf one.
        let (to_native, from_main) = mpsc::channel::<bool>();
        let vm = Arc::clone(&shared);
        let count = Arc::clone(&entered);
        let native = std::thread::spawn(move || -> Result<(), String> {
            let _flags = TransitionOverrides::set(Some(true), Some(true), None);
            let mut jt = d3k_java_thread(&vm, "sn16-native");
            let tid = jt.thread_id;
            let jt_ptr: *mut JvmThread = &mut *jt;
            let result = {
                let _jni = JniTls::context(&vm).with_thread(jt_ptr);
                push_local_frame(16);
                let run = || -> Result<(), String> {
                    let call = JniNativeCall::enter(raw_local_escapes());
                    if !d3k_in_native(jt_ptr) {
                        return Err("the native call went into native".into());
                    }
                    let _ = to_main.send(Ok(tid.0));
                    while let Ok(leaf) = from_main.recv_timeout(WAIT) {
                        let fx = if leaf {
                            ForeignJniEntry::enter_leaf(0)
                        } else {
                            ForeignJniEntry::enter()
                        };
                        count.fetch_add(1, Ordering::SeqCst);
                        drop(fx);
                        if !d3k_in_native(jt_ptr) {
                            return Err("the entry's end puts the thread back in native".into());
                        }
                        let _ = to_main.send(Ok(tid.0));
                    }
                    drop(call);
                    Ok(())
                };
                let r = run();
                if let Err(e) = &r {
                    let _ = to_main.send(Err(e.clone()));
                }
                r
            };
            vm.threads.thread_registry.mark_dead(tid);
            drop(jt);
            result
        });
        let tid = match from_native.recv_timeout(WAIT) {
            Ok(Ok(tid)) => tid,
            other => {
                drop(to_native);
                let joined = native.join();
                panic!("the native thread did not reach native: {other:?} / {joined:?}");
            }
        };
        let suspend = || {
            let mut ds = shared.debug.debug_state.lock();
            assert!(ds.jvmti_suspend(tid));
            crate::debug::publish_debugger_gates(&shared, &ds);
        };
        let resume = || {
            let mut ds = shared.debug.debug_state.lock();
            assert!(ds.jvmti_resume(tid));
            crate::debug::publish_debugger_gates(&shared, &ds);
        };
        for leaf in [false, true] {
            let before = entered.load(Ordering::SeqCst);
            suspend();
            to_native.send(leaf).expect("the native thread waits");
            // gci i18/fh: polling -- the suspension's loop-exit handshake
            // counts `main` (see `w10c_main_poll`).
            w10c_main_sleep_polling(&shared, main_tid, Duration::from_millis(150));
            let held = entered.load(Ordering::SeqCst) == before;
            let in_native = shared
                .threads
                .thread_registry
                .is_blocked(ThreadId(tid));
            // A pause requested while the thread is held: it is excluded.
            let alive = shared.threads.thread_registry.alive_count() as u32;
            let requested = w10c_main_request_polling(&shared, main_tid, alive, WAIT);
            let mut pause = PauseHeld(&shared, !requested);
            // i16a fix-up: as `a_java_thread_in_a_jni_native_holds_no_pause_and_its_jni_functions_wait_one_out`
            // drives it -- the census owes no arrival (the held thread is
            // excluded), then the plain wait returns at once. The bounded
            // `wait_for_all_timeout` is the take-over loop, which waited for
            // the requester itself (pending=1, t1 "main").
            let pending = shared.mem.gc_barrier.pending_count();
            let excluded = requested && pending == 0;
            if excluded {
                shared.mem.gc_barrier.wait_for_all();
            }
            pause.complete();
            drop(pause);
            // Resumed before any assertion, so a failure cannot strand it.
            resume();
            let ran = w10c_main_recv_polling(&shared, main_tid, &from_native, WAIT);
            assert!(held, "leaf={leaf}: no JNIEnv entry while suspended");
            assert!(in_native, "leaf={leaf}: held in native (GC-blocked)");
            assert!(
                requested && excluded,
                "leaf={leaf}: a pause completes while it is held (requested={requested} pending={pending} alive={alive})"
            );
            assert!(matches!(ran, Ok(Ok(_))), "leaf={leaf}: runs once resumed: {ran:?}");
            assert_eq!(entered.load(Ordering::SeqCst), before + 1);
        }
        // The switch off: the entry runs while the thread stays suspended.
        shared
            .debug
            .debugger_gates
            .set_suspend_at_native_transition(false);
        let before = entered.load(Ordering::SeqCst);
        suspend();
        to_native.send(false).expect("the native thread waits");
        // gci i18/fh: polling -- the entry runs while suspended and waits out
        // the suspension's loop-exit handshake, which counts `main`.
        let ran = w10c_main_recv_polling(&shared, main_tid, &from_native, WAIT);
        resume();
        assert!(matches!(ran, Ok(Ok(_))), "switch off: runs while suspended: {ran:?}");
        assert_eq!(entered.load(Ordering::SeqCst), before + 1);
        drop(to_native);
        // gci i18/fh: a loop-exit handshake spawned late would hold the
        // native thread's teardown while `main` sat in a join.
        while !native.is_finished() {
            w10c_main_poll(&shared, main_tid);
            std::thread::sleep(Duration::from_millis(1));
        }
        native
            .join()
            .expect("the native thread does not panic")
            .expect("the in-native protocol");
    }

    /// gci i17/fz (i16/sn's foreign residual,
    /// `CRATONVM_DEBUG_SUSPEND_AT_NATIVE_TRANSITION`): an idle foreign
    /// attachment (`AttachCurrentThread`) that an agent's `SuspendThread` or a
    /// JDWP `VirtualMachine.Suspend` holds stops at its next JNIEnv call
    /// (`ForeignJniEntry::enter_foreign`), still idle and GC-blocked, so
    /// another thread's pause completes without it meanwhile, and runs the
    /// function once resumed. With the switch off it runs while suspended.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn gci_i17fz_a_suspended_foreign_attachment_stops_at_its_next_jni_call() {
        use std::sync::atomic::{AtomicU32, Ordering};
        use std::sync::mpsc;
        use std::time::Duration;
        const WAIT: Duration = Duration::from_secs(30);
        let _guard = PROCESS_VM_TEST_LOCK.lock();
        let _lock = crate::runtime::jvmti::jvmti_registry_test_lock();
        let (shared, main_tid) = w10c_vm(crate::config::GcAlgorithm::Generational);
        shared
            .debug
            .debugger_gates
            .set_suspend_at_native_transition(true);
        let entered = Arc::new(AtomicU32::new(0));
        let (to_main, from_foreign) = mpsc::channel::<Result<u64, String>>();
        let (to_foreign, from_main) = mpsc::channel::<()>();
        let vm = Arc::clone(&shared);
        let count = Arc::clone(&entered);
        let foreign = std::thread::spawn(move || {
            FOREIGN_TRANSITIONS_TEST_OVERRIDE.with(|c| c.set(Some(true)));
            attach_foreign_thread_idle(Arc::clone(&vm), false, Some("fz17-foreign"));
            let tid = with_foreign_thread(|jt| jt.thread_id.0).unwrap_or(0);
            let reply = |r: Result<u64, String>| {
                let _ = to_main.send(r);
            };
            if !foreign_is_idle() {
                reply(Err("an attached thread starts idle".into()));
            } else {
                reply(Ok(tid));
                while from_main.recv_timeout(WAIT).is_ok() {
                    let text = CString::new("fz17 foreign").unwrap();
                    let s = jni_new_string_utf(get_jni_env(), text.as_ptr());
                    count.fetch_add(1, Ordering::SeqCst);
                    if s == 0 {
                        reply(Err("NewStringUTF answered NULL".into()));
                    } else if !foreign_is_idle() {
                        reply(Err("the JNI function returns the thread to idle".into()));
                    } else {
                        reply(Ok(tid));
                    }
                }
            }
            w10c_detach(&vm);
        });
        let tid = match from_foreign.recv_timeout(WAIT) {
            Ok(Ok(tid)) if tid != 0 => tid,
            other => {
                drop(to_foreign);
                let joined = foreign.join();
                panic!("the foreign thread did not attach idle: {other:?} / {joined:?}");
            }
        };
        // `jdwp` false: an agent's `SuspendThread`; true: `VirtualMachine.Suspend`.
        let suspend = |jdwp: bool| {
            let mut ds = shared.debug.debug_state.lock();
            if jdwp {
                ds.suspend_all();
            } else {
                assert!(ds.jvmti_suspend(tid));
            }
            crate::debug::publish_debugger_gates(&shared, &ds);
        };
        let resume = |jdwp: bool| {
            let mut ds = shared.debug.debug_state.lock();
            if jdwp {
                ds.resume_vm();
            } else {
                assert!(ds.jvmti_resume(tid));
            }
            crate::debug::publish_debugger_gates(&shared, &ds);
        };
        for jdwp in [false, true] {
            let before = entered.load(Ordering::SeqCst);
            suspend(jdwp);
            to_foreign.send(()).expect("the foreign thread waits");
            // gci i18/fh: polling -- the suspension's loop-exit handshake
            // counts `main` (see `w10c_main_poll`).
            w10c_main_sleep_polling(&shared, main_tid, Duration::from_millis(150));
            let held = entered.load(Ordering::SeqCst) == before;
            let blocked = shared
                .threads
                .thread_registry
                .is_blocked(ThreadId(tid));
            // A pause requested while the thread is held: it is excluded.
            let alive = shared.threads.thread_registry.alive_count() as u32;
            let requested = w10c_main_request_polling(&shared, main_tid, alive, WAIT);
            let mut pause = PauseHeld(&shared, !requested);
            let pending = shared.mem.gc_barrier.pending_count();
            let excluded = requested && pending == 0;
            if excluded {
                shared.mem.gc_barrier.wait_for_all();
            }
            pause.complete();
            drop(pause);
            // Resumed before any assertion, so a failure cannot strand it.
            resume(jdwp);
            let ran = w10c_main_recv_polling(&shared, main_tid, &from_foreign, WAIT);
            assert!(held, "jdwp={jdwp}: no JNIEnv call while suspended");
            assert!(blocked, "jdwp={jdwp}: held idle (GC-blocked)");
            assert!(
                excluded,
                "jdwp={jdwp}: a pause completes while it is held (requested={requested} pending={pending} alive={alive})"
            );
            assert!(matches!(ran, Ok(Ok(_))), "jdwp={jdwp}: runs once resumed: {ran:?}");
            assert_eq!(entered.load(Ordering::SeqCst), before + 1);
        }
        // The switch off: the call runs while the thread stays suspended.
        shared
            .debug
            .debugger_gates
            .set_suspend_at_native_transition(false);
        let before = entered.load(Ordering::SeqCst);
        suspend(false);
        to_foreign.send(()).expect("the foreign thread waits");
        // gci i18/fh: polling, as in the gci_i16sn twin.
        let ran = w10c_main_recv_polling(&shared, main_tid, &from_foreign, WAIT);
        resume(false);
        assert!(matches!(ran, Ok(Ok(_))), "switch off: runs while suspended: {ran:?}");
        assert_eq!(entered.load(Ordering::SeqCst), before + 1);
        drop(to_foreign);
        // gci i18/fh: as in the gci_i16sn twin (the detach waits out a pause).
        while !foreign.is_finished() {
            w10c_main_poll(&shared, main_tid);
            std::thread::sleep(Duration::from_millis(1));
        }
        foreign.join().expect("the foreign thread does not panic");
    }

    /// `cratonvm_thread_enter_native` / `_leave_native` (libcratonvm) called
    /// by a native that is already in native are no-ops, like on an attached
    /// thread: the host marking would empty the snapshot the native call
    /// deposited and count the thread blocked twice.
    #[test]
    fn host_native_is_a_no_op_inside_an_in_native_jni_call() {
        let (shared, _main_tid) = w10c_vm(crate::config::GcAlgorithm::Generational);
        let mut jt = d3k_java_thread(&shared, "d3k-host-native");
        let tid = jt.thread_id;
        let jt_ptr: *mut JvmThread = &mut *jt;
        {
            let _jni = JniTls::context(&shared).with_thread(jt_ptr);
            let _flags = TransitionOverrides::set(Some(true), Some(true), None);
            push_local_frame(16);
            let call = JniNativeCall::enter(raw_local_escapes());
            assert!(d3k_in_native(jt_ptr));
            let blocked = shared.mem.gc_barrier.blocked_count();
            assert!(host_thread_enter_native());
            assert_eq!(
                shared.mem.gc_barrier.blocked_count(),
                blocked,
                "not counted twice"
            );
            assert!(host_thread_leave_native());
            assert_eq!(shared.mem.gc_barrier.blocked_count(), blocked);
            assert!(d3k_in_native(jt_ptr), "still in native");
            drop(call);
            assert!(!d3k_in_native(jt_ptr));
        }
        shared.threads.thread_registry.mark_dead(tid);
    }

    /// gcd d10/j (`gcd-d10j-host-native-inside-a-jni-native-empties-live-roots`):
    /// `cratonvm_thread_enter_native` called from inside a COUNTED JNI native
    /// of a VM thread (the default flags) deposits the thread's real roots --
    /// the native's local here -- instead of emptying its snapshot, counts it
    /// blocked, and the leave wakes it the canonical way. It used to publish
    /// an empty snapshot and exclude the thread from every pause while its
    /// Java frames and locals were live.
    #[test]
    fn host_native_inside_a_counted_jni_native_keeps_the_threads_roots() {
        let (shared, _main_tid) = w10c_vm(crate::config::GcAlgorithm::Generational);
        let mut jt = d3k_java_thread(&shared, "d10j-host-in-jni");
        let tid = jt.thread_id;
        let jt_ptr: *mut JvmThread = &mut *jt;
        {
            let _jni = JniTls::context(&shared).with_thread(jt_ptr);
            // The defaults: the native call stays counted.
            let _flags = TransitionOverrides::set(Some(false), Some(false), Some(false));
            push_local_frame(16);
            let env = get_jni_env();
            let text = CString::new("d10j host").unwrap();
            let s = jni_new_string_utf(env, text.as_ptr());
            let obj = jobject_to_obj(s).expect("the native's local resolves");
            // What `JniContextGuard::install_for_native` sets for a dispatch.
            // SAFETY: the test's own boxed `JvmThread`; one field written.
            unsafe { (*jt_ptr).jni_native_class = Some(ClassId::new(7)) };
            let blocked = shared.mem.gc_barrier.blocked_count();
            assert!(host_thread_enter_native());
            assert!(
                d3k_in_native(jt_ptr),
                "excluded from pauses while in host code"
            );
            assert_eq!(shared.mem.gc_barrier.blocked_count(), blocked + 1);
            assert!(
                // SAFETY: as above; the snapshot's own lock.
                unsafe { &*jt_ptr }.root_snapshot.lock().contains(&obj),
                "the native's local is a root of the host window, not dropped"
            );
            assert!(host_thread_leave_native());
            assert!(!d3k_in_native(jt_ptr), "a counted mutator again");
            assert_eq!(shared.mem.gc_barrier.blocked_count(), blocked);
            // SAFETY: as above.
            unsafe { (*jt_ptr).jni_native_class = None };
        }
        shared.threads.thread_registry.mark_dead(tid);
    }

    /// gcd d5/f: a LEAF JNIEnv function (`GetArrayLength`,
    /// `Set/Get<Int>ArrayRegion`, `DeleteLocalRef`) called by a native in
    /// native runs in a leaf window: the thread never leaves native (its
    /// `in_blocked_region` stays up and the barrier's blocked count never
    /// moves) and the answers are right. Once a relocation was folded into the
    /// thread (simulated through its fold count) the next leaf call takes the
    /// full transition and records a fresh sync point; an out-of-range region
    /// escalates to the full transition before it raises, and the call is back
    /// in native afterwards. The call's end leaves native through the quiet
    /// leave.
    #[test]
    fn a_leaf_jni_function_runs_in_a_window_without_leaving_native() {
        use std::sync::atomic::Ordering;
        let (shared, _main_tid) = w10c_vm(crate::config::GcAlgorithm::Generational);
        let mut jt = d3k_java_thread(&shared, "d5f-leaf");
        let tid = jt.thread_id;
        let jt_ptr: *mut JvmThread = &mut *jt;
        {
            let _jni = JniTls::context(&shared).with_thread(jt_ptr);
            let _flags = TransitionOverrides::set(Some(true), Some(true), None);
            push_local_frame(16);
            let env = get_jni_env();
            let arr = jni_new_int_array(env, 4);
            assert!(
                arr != 0 && is_indirect_local_tag(arr),
                "an indirect local int[4]"
            );
            let call = JniNativeCall::enter(raw_local_escapes());
            assert!(d3k_in_native(jt_ptr));
            let blocked = shared.mem.gc_barrier.blocked_count();
            let leaf_state = || JNI_NATIVE_CALL.with(|t| t.leaf.get());

            assert_eq!(jni_get_array_length(env, arr), 4);
            let src: [JInt; 4] = [7, 8, 9, 10];
            jni_set_int_array_region(env, arr, 0, 4, src.as_ptr());
            let mut dst: [JInt; 4] = [0; 4];
            jni_get_int_array_region(env, arr, 0, 4, dst.as_mut_ptr());
            assert_eq!(dst, src, "the region round-trips");
            assert!(d3k_in_native(jt_ptr), "the leaf calls never left native");
            assert_eq!(
                shared.mem.gc_barrier.blocked_count(),
                blocked,
                "no blocked-region transition"
            );
            assert_eq!(leaf_state(), LEAF_NONE);
            let closed = JNI_NATIVE_CALL.with(|t| t.leaf_word.get().is_some_and(|w| !w.is_open()));
            assert!(closed, "the word exists and every window closed");

            // A relocation was folded into the thread: the next leaf call
            // takes the full transition and re-syncs.
            // SAFETY: the test's own boxed `JvmThread`; only an atomic.
            unsafe { &*jt_ptr }
                .gc_block_state
                .blocked_folds
                .fetch_add(1, Ordering::AcqRel);
            assert_eq!(jni_get_array_length(env, arr), 4);
            assert!(
                d3k_in_native(jt_ptr),
                "back in native after the full transition"
            );
            let synced = JNI_NATIVE_CALL.with(|t| {
                t.record.borrow().as_ref().is_some_and(|r| {
                    // SAFETY: see `NativeCallRecord::block_state`.
                    r.in_native && r.sync == NativeSync::read(&shared, unsafe { &*r.block_state })
                })
            });
            assert!(synced, "the re-entry recorded a fresh sync point");

            // Out of range: escalates before raising, and is back in native.
            jni_get_int_array_region(env, arr, 2, 5, dst.as_mut_ptr());
            assert!(
                d3k_in_native(jt_ptr),
                "back in native after an escalated leaf"
            );
            assert_eq!(leaf_state(), LEAF_NONE);
            assert!(
                take_jni_pending_exception().is_some(),
                "the out-of-range region raised"
            );

            // DeleteLocalRef is a leaf too; the slot then resolves to nothing.
            jni_delete_local_ref(env, arr);
            assert_eq!(jni_get_array_length(env, arr), 0);
            assert!(d3k_in_native(jt_ptr));
            assert_eq!(shared.mem.gc_barrier.blocked_count(), blocked);

            drop(call);
            assert!(!d3k_in_native(jt_ptr), "the call's end leaves native");
            assert_eq!(leaf_state(), LEAF_NONE);
        }
        shared.threads.thread_registry.mark_dead(tid);
    }

    /// gcd d10/j: a JNIEnv function entered through `enter_vm_only`
    /// (`NewStringUTF` here) called by a native in native goes back into
    /// native WITHOUT a second full deposit when its leave was quiet: the
    /// thread is in native again, the snapshot deposited on the way in is
    /// kept and the new local's referent is appended to it (so a collection
    /// in the next window keeps and forwards it), and the record counts the
    /// appends. A function that reached `with_jni_context` (a raise), or a
    /// fold into the thread since the deposit, re-enters with a full deposit
    /// (the count starts again at 0). Run on the
    /// `CRATONVM_JNI_IN_NATIVE_KEEP_SNAPSHOT=0` arm: with it on (the default
    /// since 2026-10-17, gci i48 jl48) a folded in-native wake keeps its
    /// snapshot and the re-entry after it may append instead.
    #[test]
    fn a_vm_only_jni_function_reenters_native_without_a_full_deposit() {
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JNI_IN_NATIVE_KEEP_SNAPSHOT", Some("0"))],
            a_vm_only_jni_function_reenters_native_without_a_full_deposit_on_the_kill_arm,
        );
    }

    fn a_vm_only_jni_function_reenters_native_without_a_full_deposit_on_the_kill_arm() {
        use std::sync::atomic::Ordering;
        let (shared, _main_tid) = w10c_vm(crate::config::GcAlgorithm::Generational);
        let mut jt = d3k_java_thread(&shared, "d10j-vm-only");
        let tid = jt.thread_id;
        let jt_ptr: *mut JvmThread = &mut *jt;
        let appended = || JNI_NATIVE_CALL.with(|t| t.record.borrow().as_ref().map(|r| r.appended));
        // `move`: the closure copies the raw pointer, so the test can still write
        // through `jt_ptr` below (a by-reference capture of the pointee is a borrow).
        let in_snapshot = move |h: JObject| -> bool {
            let Some(obj) = jobject_to_obj(h) else {
                return false;
            };
            // SAFETY: the test's own boxed `JvmThread`; its snapshot's lock.
            unsafe { &*jt_ptr }.root_snapshot.lock().contains(&obj)
        };
        {
            let _jni = JniTls::context(&shared).with_thread(jt_ptr);
            let _flags = TransitionOverrides::set(Some(true), Some(true), None);
            push_local_frame(16);
            let env = get_jni_env();
            // A redefinition anywhere in the process between the deposit and a
            // re-entry makes that re-entry a full one (correctly); the
            // incremental assertions below hold only without one.
            let redefinitions = cratonvm_classloading::class_redefinition_count();
            // SAFETY: the test's own boxed `JvmThread`, not yet in native.
            unsafe { (*jt_ptr).redefinitions_seen = redefinitions };
            let call = JniNativeCall::enter(raw_local_escapes());
            assert!(d3k_in_native(jt_ptr));
            assert_eq!(
                appended(),
                Some(0),
                "a fresh call starts from its full deposit"
            );

            let text = CString::new("d10j").unwrap();
            let s1 = jni_new_string_utf(env, text.as_ptr());
            let s2 = jni_new_string_utf(env, text.as_ptr());
            assert!(s1 != 0 && s2 != 0 && is_indirect_local_tag(s1) && is_indirect_local_tag(s2));
            assert!(d3k_in_native(jt_ptr), "back in native after each call");
            assert_eq!(
                JNI_NATIVE_CALL.with(|t| t.leaf.get()),
                LEAF_NONE,
                "the vm-only state is given back"
            );
            if cratonvm_classloading::class_redefinition_count() == redefinitions {
                assert!(
                    appended().is_some_and(|n| n >= 2),
                    "both re-entries appended instead of re-depositing: {:?}",
                    appended()
                );
            }
            assert!(in_snapshot(s1), "the first string is a root of the window");
            assert!(in_snapshot(s2), "the second string is a root of the window");

            // A raise reaches `with_jni_context`: the full way back in.
            assert_eq!(jni_new_int_array(env, -1), 0);
            let _ = take_jni_pending_exception();
            assert!(d3k_in_native(jt_ptr));
            assert_eq!(appended(), Some(0), "an escalated function re-deposits");

            // A fold into the thread since the deposit: the leave is not
            // quiet, and the re-entry is a full deposit with a fresh sync.
            // SAFETY: the test's own boxed `JvmThread`; only an atomic.
            unsafe { &*jt_ptr }
                .gc_block_state
                .blocked_folds
                .fetch_add(1, Ordering::AcqRel);
            let s3 = jni_new_string_utf(env, text.as_ptr());
            assert!(s3 != 0);
            assert!(d3k_in_native(jt_ptr));
            assert_eq!(appended(), Some(0), "a fold forces the full deposit");
            let synced = JNI_NATIVE_CALL.with(|t| {
                t.record.borrow().as_ref().is_some_and(|r| {
                    // SAFETY: see `NativeCallRecord::block_state`.
                    r.in_native && r.sync == NativeSync::read(&shared, unsafe { &*r.block_state })
                })
            });
            assert!(synced, "the full re-entry recorded a fresh sync point");
            assert!(in_snapshot(s3), "the full deposit roots the new local too");
            assert!(in_snapshot(s1), "and the older ones");

            drop(call);
            assert!(!d3k_in_native(jt_ptr), "the call's end leaves native");
            assert_eq!(
                shared.mem.gc_barrier.blocked_count(),
                0,
                "every in-native entry was released exactly once"
            );
        }
        shared.threads.thread_registry.mark_dead(tid);
    }

    /// gci i27/kd (`gch-h2jr-review-findings-RETIRED-RULING-20261018` item 9): the JNI switch
    /// package is read once per VM, so two VMs built under different
    /// overrides keep their own answers in one process (the process
    /// `OnceLock` answered every VM with the first reader's), and
    /// `jni_switches` answers for the VM of the thread's JNI context.
    #[test]
    fn gci_i27kd_jni_switches_are_read_per_vm_and_follow_the_context() {
        let build = |value: &str| {
            Arc::new(cratonvm_types::flags::with_thread_overrides(
                &[
                    ("CRATONVM_JNI_BULK_ARRAY_COPY", Some(value)),
                    ("CRATONVM_JNI_INDIRECT_LOCALS", Some(value)),
                ],
                || SharedVm::new(crate::config::VmConfig::default()),
            ))
        };
        let killed = build("0");
        let on = build("1");
        let k = jni_switches_of(&killed);
        let o = jni_switches_of(&on);
        assert!(!k.bulk_array_copies && !k.indirect_locals);
        assert!(
            !k.foreign_transitions,
            "the foreign transitions are refused without indirect locals"
        );
        assert!(o.bulk_array_copies && o.indirect_locals);
        assert_ne!(k, o, "each VM keeps its own package");

        let prev = JNI_SHARED_VM.with(|c| c.borrow().clone());
        restore_jni_context(Some(Arc::clone(&killed)));
        let in_killed = jni_switches();
        restore_jni_context(Some(Arc::clone(&on)));
        let in_on = jni_switches();
        restore_jni_context(prev);
        assert_eq!(in_killed, k, "the context's VM answers");
        assert_eq!(in_on, o, "the context's VM answers");
        // No context and no attachment: the flag snapshot, read once per OS
        // thread (the memo is cleared first: this test thread may have
        // answered before).
        let _ = JNI_NATIVE_CALL.try_with(|t| t.switches_memo.set(None));
        let bare = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JNI_BULK_ARRAY_COPY", Some("0"))],
            || {
                if JNI_SHARED_VM.with(|c| c.borrow().is_none()) && !is_foreign_attached() {
                    Some(jni_switches())
                } else {
                    None
                }
            },
        );
        let memo = JNI_NATIVE_CALL.with(|t| t.switches_memo.take());
        if let Some(bare) = bare {
            assert!(!bare.bulk_array_copies, "the per-thread override reaches it");
            assert_eq!(memo, Some(bare), "and is memoised for this OS thread");
        }
    }

    /// gcd d10/j: the package rule of the three JNI switches.
    #[test]
    fn jni_switches_move_as_one_package_and_refuse_arm_c() {
        // gcf f1/j: the envelope-first deposit is unset here, i.e. on exactly
        // when the native transitions are (asserted on its own below).
        // gcf f2/j: so is the repeat deposit.
        let s =
            |native, indirect, foreign| jni_switches_from(native, indirect, foreign, None, None);
        let sw = |indirect_locals, foreign_transitions, native_transitions| JniSwitches {
            indirect_locals,
            foreign_transitions,
            native_transitions,
            deposit_envelope_first: native_transitions,
            deposit_repeat: native_transitions,
            repeat_audit: false,
            bulk_array_copies: false,
            in_native_no_signal: native_transitions,
            ffm_repeat: false,
            in_native_doors: native_transitions,
            // gch h1/jw: outside the package rule, on unless killed.
            foreign_tid_publish: true,
            // gch h2/jr: the pure rule leaves it off.
            in_native_arrive_no_wait: false,
            // gci i1/jn (the flip): on with the package.
            in_native_band_at_pause: native_transitions,
            // gci i5/fj: the pure rule leaves it off.
            foreign_quiet_idle: false,
            // gci i20/jt: the pure rule leaves it off.
            in_native_lockfree_leave: false,
            // gci i48 jl48: on unless killed.
            in_native_keep_snapshot: true,
            // gcj j1/jn: the pure rule leaves the three latched opt-ins off.
            in_native_band_narrow: false,
            in_native_proven_depth_credit: false,
            foreign_alloc_ladder: false,
            // gcj j1/jn: on unless killed.
            array_vm_limit: true,
            // gcj j2/jn2: the pure rule leaves the two ledger cuts off.
            switches_once_per_call: false,
            in_native_keep_tlab: false,
            // t1 w8 JNICUT: on unless killed.
            in_native_band_at_pause_g1: true,
            // gcj j2/jn2: the exact-mid kills on, the selection off, the
            // NewString edges on.
            static_exact_mid: true,
            nonvirtual_exact_mid: true,
            virtual_upcall_selects: false,
            new_string_hotspot_edges: true,
            // JIT round 21 wave 19 (lane jnilazy): on with the package.
            in_native_lazy: native_transitions,
        };
        // gc JNI retirement (2026-10-10): the defaults are arm D.
        assert_eq!(
            s(None, None, None),
            sw(true, true, false),
            "the defaults: arm D"
        );
        assert_eq!(
            s(Some(true), None, None),
            sw(true, true, true),
            "the package switch"
        );
        assert_eq!(
            s(Some(true), Some(false), None),
            sw(false, false, true),
            "an explicit off wins, and takes the foreign transitions with it"
        );
        assert_eq!(
            s(None, Some(false), None),
            sw(false, false, false),
            "the kill switch: arm A"
        );
        assert_eq!(s(Some(true), None, Some(false)), sw(true, false, true));
        assert_eq!(s(None, None, Some(false)), sw(true, false, false), "arm B");
        assert_eq!(s(None, Some(true), None), sw(true, true, false), "arm D");
        assert_eq!(
            s(None, Some(false), Some(true)),
            sw(false, false, false),
            "arm C is refused"
        );
        assert_eq!(
            s(Some(false), None, None),
            sw(true, true, false),
            "the package off: arm D"
        );
        assert_eq!(
            s(Some(false), Some(false), Some(true)),
            sw(false, false, false)
        );
        assert_eq!(
            s(Some(false), Some(true), Some(true)),
            sw(true, true, false)
        );

        assert_eq!(jni_switch_value(None), None);
        // gcf f1/j: the envelope-first deposit rides on the package and has
        // its own `=0` kill switch; set on alone it stays off (nothing to cut).
        let env_first =
            |native, env| jni_switches_from(native, None, None, env, None).deposit_envelope_first;
        assert!(env_first(Some(true), None), "on with the package");
        assert!(!env_first(Some(true), Some(false)), "its kill switch");
        assert!(!env_first(None, Some(true)), "never without the package");
        assert!(!env_first(Some(false), Some(true)));
        assert!(!env_first(None, None), "the defaults: off");
        // gcf f2/j: the repeat deposit, the same rule.
        let repeat = |native, r| jni_switches_from(native, None, None, None, r).deposit_repeat;
        assert!(repeat(Some(true), None), "on with the package");
        assert!(!repeat(Some(true), Some(false)), "its kill switch");
        assert!(!repeat(None, Some(true)), "never without the package");
        assert!(!repeat(None, None), "the defaults: off");
        let off = jni_switches_from(Some(true), None, None, None, None);
        assert!(!off.repeat_audit && !off.bulk_array_copies, "latched apart");
        // gcg g5/jn: the bulk copies are default ON, `=0` (or any off word) kills.
        assert!(bulk_array_copies_from(None), "the default: on");
        assert!(bulk_array_copies_from(jni_switch_value(Some("1"))));
        assert!(
            !bulk_array_copies_from(jni_switch_value(Some("0"))),
            "its kill switch"
        );
        assert!(!bulk_array_copies_from(jni_switch_value(Some("off"))));
        assert!(
            bulk_array_copies_from(jni_switch_value(Some(""))),
            "empty is unset"
        );
        // gch h1/jw: the attached thread's tid publish, default ON, `=0` kills.
        assert!(foreign_tid_publish_from(None), "the default: on");
        assert!(foreign_tid_publish_from(jni_switch_value(Some("1"))));
        assert!(
            !foreign_tid_publish_from(jni_switch_value(Some("0"))),
            "its kill switch"
        );
        assert!(!foreign_tid_publish_from(jni_switch_value(Some("off"))));
        assert!(
            foreign_tid_publish_from(jni_switch_value(Some(""))),
            "empty is unset"
        );
        assert!(off.foreign_tid_publish, "outside the package rule");
        // gch h2/jr: the no-wait in-native arrival, default OFF, only with
        // the package, on only when set on.
        assert!(
            !in_native_arrive_no_wait_from(true, None),
            "the default: off"
        );
        assert!(in_native_arrive_no_wait_from(
            true,
            jni_switch_value(Some("1"))
        ));
        assert!(!in_native_arrive_no_wait_from(
            true,
            jni_switch_value(Some("0"))
        ));
        assert!(
            !in_native_arrive_no_wait_from(true, jni_switch_value(Some(""))),
            "empty is unset"
        );
        assert!(
            !in_native_arrive_no_wait_from(false, Some(true)),
            "never without the package"
        );
        assert!(!off.in_native_arrive_no_wait, "latched apart");
        // gch h4/bp, gci i1/jn (the flip): the band at the pause, default ON
        // with the package's no-signal mark, `=0` (any off word) kills it.
        assert!(in_native_band_at_pause_from(true, None), "the default: on");
        assert!(in_native_band_at_pause_from(true, jni_switch_value(Some("1"))));
        assert!(!in_native_band_at_pause_from(true, jni_switch_value(Some("0"))), "its kill switch");
        assert!(!in_native_band_at_pause_from(true, jni_switch_value(Some("off"))));
        assert!(in_native_band_at_pause_from(true, jni_switch_value(Some(""))), "empty is unset: on");
        assert!(!in_native_band_at_pause_from(false, Some(true)), "never without the package");
        assert!(!in_native_band_at_pause_from(false, None), "never without the package");
        assert!(off.in_native_band_at_pause, "the pure rule: on with the package");
        assert!(
            !jni_switches_from(None, None, None, None, None).in_native_band_at_pause,
            "the defaults (no package): off"
        );
        assert_eq!(jni_switch_value(Some("")), None, "empty is unset");
        assert_eq!(jni_switch_value(Some("  ")), None);
        for off in ["0", "false", "off", "no", " 0 "] {
            assert_eq!(jni_switch_value(Some(off)), Some(false), "{off:?}");
        }
        for on in ["1", "true", "on", "yes"] {
            assert_eq!(jni_switch_value(Some(on)), Some(true), "{on:?}");
        }
    }

    /// JIT round 16 wave 11 (lane jnieintr): the in-native bracket's
    /// no-signal mark rides on the package with its own `=0` kill, and the
    /// FFM repeat arms the in-native repeat without the package, only for a
    /// flag-raising deposit.
    #[test]
    fn in_native_no_signal_and_ffm_repeat_switch_rules() {
        assert!(in_native_no_signal_from(true, None), "on with the package");
        assert!(in_native_no_signal_from(true, Some(true)));
        assert!(
            !in_native_no_signal_from(true, Some(false)),
            "its kill switch"
        );
        assert!(
            !in_native_no_signal_from(false, None),
            "never without the package"
        );
        assert!(!in_native_no_signal_from(false, Some(true)));

        let base = jni_switches_from(None, None, None, None, None);
        assert!(
            !base.ffm_repeat && !base.in_native_no_signal,
            "the defaults: off"
        );
        assert!(!repeat_armed_from(&base, true), "the default arms nothing");
        let ffm = JniSwitches {
            ffm_repeat: true,
            ..base
        };
        assert!(repeat_armed_from(&ffm, true), "the FFM switch, no package");
        assert!(!repeat_armed_from(&ffm, false), "never a no-flag deposit");
        let pkg = jni_switches_from(Some(true), None, None, None, None);
        assert!(
            repeat_armed_from(&pkg, true),
            "the package's own repeat, unchanged"
        );
        let pkg_killed = jni_switches_from(Some(true), None, None, None, Some(false));
        assert!(
            !repeat_armed_from(&pkg_killed, true),
            "the package repeat's kill"
        );
    }

    /// JIT round 21 wave 19 (lane jnilazy, FF3-3): the lazy JNI in-native
    /// state is on with the package (and its doors), off without it whatever
    /// the switch says, and `CRATONVM_JNI_IN_NATIVE_LAZY=0` kills it.
    #[test]
    fn jni_in_native_lazy_rides_the_package_and_has_a_kill_switch() {
        assert!(in_native_lazy_from(true, None), "on with the package");
        assert!(in_native_lazy_from(true, Some(true)));
        assert!(!in_native_lazy_from(true, Some(false)), "the kill switch");
        assert!(!in_native_lazy_from(false, None), "never without the package");
        assert!(!in_native_lazy_from(false, Some(true)));
        let pkg = jni_switches_from(Some(true), None, None, None, None);
        assert!(pkg.in_native_lazy, "the pure rule: on with the package");
        let base = jni_switches_from(None, None, None, None, None);
        assert!(!base.in_native_lazy, "the defaults: the package is off");
    }

    /// JIT round 16 wave 11 (lane jnieintr): the in-native bracket raises
    /// `foreign_native` before the deposit, lowers it first on the way out
    /// and on the incremental re-entry raises it before `in_blocked_region`
    /// -- the order `ffm_in_native_signal_exempt`'s argument needs (a running
    /// thread is never read as exempt). A source pin: the three bodies need a
    /// whole VM to run.
    #[test]
    fn in_native_bracket_orders_the_foreign_native_mark() {
        fn item(src: &'static str, start: &str) -> &'static str {
            let at = src.find(start).expect(start);
            let rest = &src[at..];
            // Up to the next item (no brace inside a literal: brace ratchets).
            &rest[..rest[1..].find("\nfn ").expect("next fn") + 1]
        }
        let src: &'static str = include_str!("jni.rs");
        let body = |start: &str| item(src, start);
        let pos = |b: &str, needle: &str| b.find(needle).expect(needle);
        let enter = body("fn native_call_enter_native(");
        assert!(
            pos(enter, "raise_foreign_native(thread)") < pos(enter, ".deposit_root_snapshot()"),
            "raised before the deposit raises in_blocked_region"
        );
        let reenter = body("fn native_call_reenter_incremental(");
        assert!(
            pos(reenter, "raise_foreign_native(thread)") < pos(reenter, ".in_blocked_region"),
            "raised before the blocked flag on the incremental re-entry"
        );
        let leave = body("fn native_call_leave_native(");
        assert!(
            pos(leave, ".foreign_native") < pos(leave, "leave_in_native_if("),
            "lowered while still blocked"
        );
        assert!(
            pos(leave, ".foreign_native") < pos(leave, "leave_in_native_lockfree_if("),
            "lowered while still blocked (gci i20/jt, the lock-free leave)"
        );
    }

    /// gci i20/jt (`CRATONVM_JNI_IN_NATIVE_LOCKFREE_LEAVE`): the lock-free
    /// in-native leave is sound only if the production census counts a
    /// thread whose `in_native_leaving` is up, reading that word BEFORE the
    /// blocked flag (`GcBarrier::leave_in_native_lockfree_if`'s Dekker
    /// argument). A source pin: a census that went back to the bare flag
    /// would silently exclude a running thread.
    #[test]
    fn gci_i20jt_the_production_census_reads_the_leaving_word_first() {
        fn method(src: &'static str, start: &str) -> &'static str {
            let at = src.find(start).expect(start);
            let rest = &src[at..];
            &rest[..rest.find("\n    \u{7d}\n").expect("method end")]
        }
        let registry: &'static str = include_str!("../threading/thread_registry.rs");
        for census in [
            "fn alive_count_blocked_and_os_tids_for_inner(",
            "fn alive_count_blocked_and_os_tids_inner(",
        ] {
            let body = method(registry, census);
            assert!(body.contains(".census_blocked()"), "{census} reads census_blocked");
            assert!(
                !body.contains(".in_blocked_region.load("),
                "{census} reads no bare blocked flag"
            );
        }
        let state: &'static str = include_str!("../threading/jvm_thread.rs");
        let rule = method(state, "pub fn census_blocked(");
        let pos = |needle: &str| rule.find(needle).expect(needle);
        assert!(
            pos("in_native_leaving") < pos("in_blocked_region"),
            "the leaving word is read first"
        );
    }

    /// gch h4/bp (`CRATONVM_JNI_IN_NATIVE_BAND_AT_PAUSE`): the band a JNI
    /// native call leaves to the pause -- its rule (pure) and where the
    /// bracket records and withdraws it (source pins: the bracket needs a
    /// whole VM and C code to run).
    #[test]
    fn gch_h4bp_in_native_band_rule_and_bracket_order() {
        // [lo, top): lo is the SP rounded down to a word, the spill inside it.
        assert_eq!(
            in_native_band_from(0x7000_1003, 0x7000_2000, 0x7010_0000),
            Some((0x7000_1000, 0x7010_0000))
        );
        assert_eq!(
            in_native_band_from(0x7000_3000, 0x7000_2000, 0x7010_0000),
            None,
            "the spill below the band"
        );
        assert_eq!(
            in_native_band_from(0x7000_1000, 0x700f_ffd0, 0x7010_0000),
            None,
            "the spill not whole below the top"
        );
        assert_eq!(
            in_native_band_from(0x7000_1000, 0x700f_ffc0, 0x7010_0000),
            Some((0x7000_1000, 0x7010_0000)),
            "a spill ending at the top"
        );
        assert_eq!(in_native_band_from(0, 0x40, 0x1000), None, "no SP");
        assert_eq!(
            in_native_band_from(0x1000, usize::MAX - 8, usize::MAX),
            None,
            "an overflowing spill"
        );
        // gci i1/jn: the switch is on by default with the package (a
        // dispatch captures and a compiled call bands), off without it.
        assert!(jni_switches_from(Some(true), None, None, None, None).in_native_band_at_pause);
        assert!(!jni_switches_from(None, None, None, None, None).in_native_band_at_pause);

        fn item(src: &'static str, start: &str) -> &'static str {
            let at = src.find(start).expect(start);
            let rest = &src[at..];
            &rest[..rest[1..].find("\nfn ").expect("next fn") + 1]
        }
        let src: &'static str = include_str!("jni.rs");
        let pos = |b: &str, needle: &str| b.find(needle).expect(needle);
        // Recorded before the deposit raises the flag; the deposit runs scoped.
        let enter = item(src, "fn native_call_enter_native(");
        assert!(pos(enter, "store_in_native_band(") < pos(enter, ".deposit_root_snapshot()"));
        assert!(enter.contains("with_band_at_pause_deposit(band.is_some()"));
        // Withdrawn on both ways out, the full wake's after the flag is down.
        let leave = item(src, "fn native_call_leave_native(");
        assert!(pos(leave, "clear_in_native_band(") > pos(leave, "if !keep_origins"));
        assert!(
            leave.rfind("clear_in_native_band(").expect("full wake")
                > pos(leave, ".check_post_block_gc_in_native(keep_origins)")
        );
        // The dispatch captures in its own frame before the entry, keeps the
        // spill past the leave.
        let at = src
            .find("unsafe fn dispatch_jni_native_census(")
            .expect("dispatch");
        let end = at
            + src[at..]
                .find("unsafe fn call_jni_marshalled(")
                .expect("next");
        let dispatch = &src[at..end];
        assert!(
            pos(dispatch, "CalleeSavedSpill::capture()")
                < pos(dispatch, "JniNativeCall::enter_banded(")
        );
        assert!(
            pos(dispatch, "JniNativeCall::enter_banded(") < pos(dispatch, "call_jni_marshalled(")
        );
        assert!(pos(dispatch, "drop(in_native)") < pos(dispatch, "spill.keep_alive()"));
    }

    /// gci i48 lane jl48 (`ja11_w_tag`, i10al item 4): the in-native leave's
    /// full wake is the keeping door, told whether the call may go back
    /// incrementally; a kept wake lets a vm-only function own the incremental
    /// re-entry, restarting the record's sync at the wake, and gives the
    /// origins back like a quiet leave when it cannot own it. Source pins
    /// (the bracket needs a whole VM and C code to run); the wake itself is
    /// covered by `vm_exec`'s `gci_i48_jl48_*` units.
    #[test]
    fn gci_i48_jl48_the_full_in_native_wake_keeps_and_reenters_incrementally() {
        fn item(src: &'static str, start: &str) -> &'static str {
            let at = src.find(start).expect(start);
            let rest = &src[at..];
            &rest[..rest[1..].find("\n    fn ").map_or(rest.len(), |e| e + 1)]
        }
        let src: &'static str = include_str!("jni.rs");
        let pos = |b: &str, needle: &str| b.find(needle).expect(needle);
        let leave = &src[src.find("fn native_call_leave_native(").expect("leave")..];
        let leave = &leave[..leave.find("\n}\n").expect("leave end")];
        assert!(leave.contains(".check_post_block_gc_in_native(keep_origins)"));
        assert!(!leave.contains(".check_post_block_gc()"), "never the refreshing door");
        assert!(leave.contains("NativeLeave::KeptWake"));
        let enter = item(src, "    fn enter_from_native(vm_only: bool)");
        let left = pos(enter, "native_call_leave_native(");
        assert!(left < pos(enter, "let kept = leave == NativeLeave::KeptWake;"));
        assert!(enter.contains("let quiet = leave == NativeLeave::Quiet || kept;"));
        // The sync restarts only for an owned entry, after the ownership claim.
        let owned = pos(enter, "t.leaf.set(LEAF_VM_ONLY);");
        let restart = pos(enter, "if kept && owns_vm_only {");
        assert!(owned < restart && restart < pos(enter, "rec.sync = now;"));
        assert!(pos(enter, "NativeSync::read(shared_vm,") > restart);
        assert_eq!(JniPhase::NAMES.len(), JniPhase::COUNT);
        assert_eq!(JniPhase::NAMES[JniPhase::LeaveWakeKept as usize], "leave_wake_kept");
    }

    /// gci i24/bp (`CRATONVM_JNI_IN_NATIVE_PROVEN_DEPTH_CREDIT`): the entry
    /// zeroes the proven depth before its deposit and runs the deposit inside
    /// the proof scope nested in the band scope; the deposit records the depth
    /// after its proof and before it raises the flag; the withdrawal zeroes the
    /// depth with the band. Source pins (the bracket needs a whole VM and C
    /// code to run); the switch itself is off by default.
    #[test]
    fn gci_i24bp_the_bracket_records_and_withdraws_the_proven_depth() {
        fn item(src: &'static str, start: &str) -> &'static str {
            let at = src.find(start).expect(start);
            let rest = &src[at..];
            &rest[..rest[1..].find("\nfn ").expect("next fn") + 1]
        }
        let src: &'static str = include_str!("jni.rs");
        let pos = |b: &str, needle: &str| b.find(needle).expect(needle);
        let enter = item(src, "fn native_call_enter_native(");
        assert!(pos(enter, ".in_native_proven_jit_depth") < pos(enter, ".deposit_root_snapshot()"));
        assert!(
            pos(enter, "with_band_at_pause_deposit(band.is_some()")
                < pos(enter, "with_band_at_pause_proof(prove")
        );
        assert!(pos(enter, "with_band_at_pause_proof(prove") < pos(enter, ".deposit_root_snapshot()"));
        assert!(enter.contains("band.is_some() && in_native_proven_depth_credit_admits(shared)"));
        let clear = item(src, "fn clear_in_native_band(");
        assert!(clear.contains(".in_native_proven_jit_depth"));
        let admits = item(src, "fn in_native_proven_depth_credit_admits(");
        assert!(admits.contains("is_generational()"), "Generational only");
        let exec: &'static str = include_str!("../vm/vm_exec.rs");
        let at = exec
            .find("fn deposit_root_snapshot_inner_with(")
            .expect("the deposit");
        let deposit = &exec[at..at + exec[at..].find("\n    }\n").expect("deposit end")];
        let record = pos(deposit, ".in_native_proven_jit_depth");
        assert!(pos(deposit, "let thread_chain_proven") < record, "after the proof");
        assert!(
            record < deposit.rfind(".in_blocked_region").expect("the flag raise"),
            "before the flag goes up"
        );
        assert!(deposit.contains("band_at_pause_proof_armed()"));
    }

    /// gci i28/nb (P5/nb): a band narrows to the chain top only when that top
    /// lies strictly inside it and the narrowed band still holds the
    /// dispatch's callee-saved spill (`gch-h4bp-review-findings` item 4: a
    /// value the compiled caller keeps only in a register is in that spill)
    /// and passes the lazy claim's bounds; otherwise the whole band is kept.
    #[test]
    fn gci_i28nb_the_band_narrows_only_around_the_spill() {
        let sp = 0x7000_1000usize;
        let spill = 0x7000_2000usize;
        let top = 0x7010_0000usize;
        let wide = in_native_band_from(sp, spill, top).expect("the whole band");
        assert_eq!(wide, (sp, top));
        assert_eq!(
            in_native_band_narrowed_from(sp, spill, wide, None),
            (wide, false),
            "no proof: the whole band"
        );
        assert_eq!(
            in_native_band_narrowed_from(sp, spill, wide, Some(0x7000_4000)),
            ((sp, 0x7000_4000), true),
            "narrowed to the chain"
        );
        assert_eq!(
            in_native_band_narrowed_from(sp, spill, wide, Some(0x7000_2040)),
            ((sp, 0x7000_2040), true),
            "the spill's last word is still inside"
        );
        assert_eq!(
            in_native_band_narrowed_from(sp, spill, wide, Some(0x7000_2038)),
            (wide, false),
            "a chain top inside the spill keeps the whole band"
        );
        assert_eq!(
            in_native_band_narrowed_from(sp, spill, wide, Some(top)),
            (wide, false),
            "not narrower"
        );
        assert_eq!(
            in_native_band_narrowed_from(sp, spill, wide, Some(top + 8)),
            (wide, false)
        );
        assert_eq!(
            in_native_band_narrowed_from(sp, spill, wide, Some(sp)),
            (wide, false),
            "an empty band"
        );
        assert_eq!(
            in_native_band_narrowed_from(sp, spill, wide, Some(sp - 8)),
            (wide, false)
        );
    }

    /// gci i28/nb: the narrowing is default ON (`runtime_flag_default_on`,
    /// `=0` kills; WARNING gck-jn2-user-flip-20261025, opt-in before), decided after
    /// the whole band passed its own rule, and only through the pure rule
    /// above; its census phases are named. Source pins (the band needs a
    /// compiled caller and C code to run).
    #[test]
    fn gci_i28nb_the_narrowing_is_opt_in_and_after_the_whole_band() {
        fn item(src: &'static str, start: &str) -> &'static str {
            let at = src.find(start).expect(start);
            let rest = &src[at..];
            &rest[..rest[1..].find("\nfn ").expect("next fn") + 1]
        }
        let src: &'static str = include_str!("jni.rs");
        let pos = |b: &str, needle: &str| b.find(needle).expect(needle);
        let band = item(src, "fn in_native_band_at_pause(");
        // gcj j1/jn: the switch is the VM's latched copy now.
        assert!(
            pos(band, "let wide = in_native_band_from(sp, spill_at, top)")
                < pos(band, "if !switches.in_native_band_narrow")
        );
        assert!(
            pos(band, "if !switches.in_native_band_narrow")
                < pos(band, "in_native_band_chain_top_why(wide.0, top)")
        );
        assert!(!band.contains("in_native_band_narrow_enabled()"), "no per-call read");
        let read = item(src, "    fn read_flags(report: bool) -> Self {");
        assert!(read.contains("switches.in_native_band_narrow = in_native_band_narrow_enabled();"));
        assert!(band.contains("in_native_band_narrowed_from(sp, spill_at, wide,"));
        let switch = item(src, "fn in_native_band_narrow_enabled(");
        assert!(switch.contains("runtime_flag_default_on("), "default on (gck flip)");
        assert!(!switch.contains("runtime_flag_on("), "not opt-in any more");
        assert_eq!(JniPhase::NAMES.len(), JniPhase::COUNT);
        let name = |p: JniPhase| JniPhase::NAMES[p as usize];
        assert_eq!(name(JniPhase::DepBandNarrowProbe), "dep_band_narrow_probe");
        assert_eq!(name(JniPhase::DepBandNarrowed), "dep_band_narrowed");
        assert_eq!(name(JniPhase::DepBandNarrowMemo), "dep_band_narrow_memo");
    }

    /// JIT round 16 wave 12 (lane inpkg): the door fixes ride on the package
    /// with their own `=0` kill; the staged flip turns the package on only
    /// when `CRATONVM_JNI_NATIVE_TRANSITIONS_DEFAULT=1` and the package
    /// switch itself is unset, and an explicit package setting always wins.
    #[test]
    fn in_native_doors_and_staged_default_rules() {
        assert!(in_native_doors_from(true, None), "on with the package");
        assert!(in_native_doors_from(true, Some(true)));
        assert!(!in_native_doors_from(true, Some(false)), "its kill switch");
        assert!(
            !in_native_doors_from(false, None),
            "never without the package"
        );
        assert!(!in_native_doors_from(false, Some(true)));
        let base = jni_switches_from(None, None, None, None, None);
        assert!(!base.in_native_doors, "the defaults: off");
        let pkg = jni_switches_from(Some(true), None, None, None, None);
        assert!(pkg.in_native_doors, "the pure rule: equal to the package");

        // WARNING gci-user-flip-20261013: unset is ON since the user's flip.
        assert!(
            native_transitions_default_from(None),
            "flipped: unset is on"
        );
        assert!(!native_transitions_default_from(Some(false)));
        assert!(native_transitions_default_from(Some(true)), "explicit on");
        let n = native_transitions_explicit_or_default;
        // gci i8/rv: since the user's flip (gci-user-flip-20261013) the unset
        // pair reads the package ON; this line still said "unchanged" (None).
        assert_eq!(n(None, None), Some(true), "the flipped default: unset is on");
        assert_eq!(n(None, Some(false)), None);
        assert_eq!(n(None, Some(true)), Some(true), "the staged default");
        assert_eq!(
            n(Some(false), Some(true)),
            Some(false),
            "an explicit off wins"
        );
        assert_eq!(n(Some(true), None), Some(true));
        assert_eq!(
            n(Some(true), Some(false)),
            Some(true),
            "an explicit on wins"
        );
        // With the staged default on, the whole package is on, as with the
        // package switch itself.
        assert_eq!(
            jni_switches_from(n(None, Some(true)), None, None, None, None),
            pkg
        );
    }

    /// JIT round 16 wave 12 (lane inpkg): the two door fixes sit where the
